window.kbPageData["views/entry/k-b01315126a87f4fb"] = {"key":"entry/k-b01315126a87f4fb","state":{"route":"entry/k-b01315126a87f4fb"},"node":{"id":"k-b01315126a87f4fb","mode":"k","title":"条件蕴涵的传递性","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2025 副省级 行测#113"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"如果P能推出Q，Q又能推出R，那么P能推出R。若R由多个并列条件组成，这些条件都随P成立而成立。","review":{"definition":"如果P能推出Q，Q又能推出R，那么P能推出R。若R由多个并列条件组成，这些条件都随P成立而成立。","explanation":"按题干，能为企业参与出口竞争提供真正的市场根基，就必须具备完备的商业规则环境。要形成这种环境，又必须推进全方位开放并建立全国统一大市场，且加强执法效率和司法保障。串联这两层必要条件，可知其中任一要求未满足，就无法提供题述市场根基，对应D项。C项的要素流动和配置效率要求属于市场体系这条推导链，题干没有给出从商业规则环境推出这些要求的条件。","references":[],"evidence":"将①④串联可得到⑥","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 副省级 行测#113":{"paper":"国考 2025 副省级 行测","n":113,"mod":"判断推理","src":["ffe12c35a46d4df574ec.pdf",22],"asrc":["ff0b352b44d417525086.pdf",36],"card":"ab41691f6bb1952c10f18674","links":[{"id":"k-b01315126a87f4fb","role":"解题依据","why":"若甲推出乙、乙推出丙，则甲推出丙，据此可串联两层必要条件。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-b01315126a87f4fb":[["国考 2025 副省级 行测#113"]]}};
